--=========================================-- Author:		<Jose Roman>-- Create date: <06-03-2018>-- Description:	<Consulta para las cartas de opinion del Sat, se agregan parametros de contrato y columna vigente>-- =============================================CREATE procedure [dbo].[CF_SP_ConsultarCartasOpinionSAT]	@IdProveedor INT,	/*--------------------parametros contrato  --------------------*/    @IdContrato    INT = null,    @IdUsuario     INT = null,    @FechaRegistro DATETIME = null	/*----
---------------------------------------------------------*/ASBEGIN	SELECT IdCartaOponionSat AS IdCartaOpinionSat, 			NombreCarta, 			FechaExpedicion, 			CASE WHEN Opinion = 1 THEN 'Favorable' ELSE 'No Favorable' END AS Opinion,			CASE WHEN vigente
 = 1 THEN 'Si' ELSE 'No' END AS vigente	 		FROM dbo.CF_CartaOpinionSAT		WHERE IdProveedor = @IdProveedor AND Eliminado = 0END